export const farRegionAt = (x, y) => { let best = "mire", d = 1e9; for (const [k, r] of Object.entries(FAR_REGIONS)) { const q = ((x - r[3]) / r[5]) ** 2 + ((y - r[4]) / r[6]) ** 2; if (q < d) { d = q; best = k; } } return best; };
const hub = (k) => FAR_REGIONS[k];
const B = (id, k, w, h, st, name) => [id, hub(k)[1] - Math.floor(w / 2), hub(k)[2] - 6 - h, w, h, st, name];
